import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_DIR = path.resolve(__dirname, 'data');

export async function listTools() {
  return [
    {
      name: 'file_metadata',
      description: 'Return metadata (relative path, byte size, lowercase extension) for a file under the workspace data directory. Does not expose file contents.',
      inputSchema: {
        type: 'object',
        properties: {
          path: {
            type: 'string',
            description: 'Path to the file, relative to the data directory.',
          },
        },
        required: ['path'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'file_metadata') {
    throw new Error('Unknown tool: ' + name);
  }
  const input = args || {};
  const rel = input.path;
  if (typeof rel !== 'string' || rel.length === 0) {
    throw new Error('path is required');
  }
  // reject absolute paths
  if (path.isAbsolute(rel)) {
    throw new Error('path must be relative to the data directory');
  }
  const abs = path.resolve(DATA_DIR, rel);
  // traversal check
  const relFromData = path.relative(DATA_DIR, abs);
  if (relFromData.startsWith('..') || path.isAbsolute(relFromData)) {
    throw new Error('path escapes the data directory');
  }
  let stat;
  try {
    stat = fs.statSync(abs);
  } catch (e) {
    throw new Error('File not found: ' + rel);
  }
  if (!stat.isFile()) {
    throw new Error('Not a file: ' + rel);
  }
  const ext = path.extname(abs).toLowerCase();
  const text = `path: ${rel}\nsize: ${stat.size}\nextension: ${ext}`;
  return {
    content: [{ type: 'text', text }],
  };
}
